# COMMAND ----------

# DBTITLE 1,Import functions
from pyspark.sql import functions as F
from pyspark.sql.window import Window

# COMMAND ----------

df_csv=spark.read.csv(f"""/Volumes/de_{env}/dufrain_bronze_{env}/landing/csv_files/*.csv""",
                  header=False,
                  sep=',',
                  inferSchema=True)
df_csv.display()

# COMMAND ----------

# MAGIC %md
# MAGIC ### Task 3: Data preparation
# MAGIC
# MAGIC The DataFrame needs some work before it is usable. Row numbers below refer to the rows as displayed in Task 2, counting from 1.
# MAGIC
# MAGIC 1. The column headers are on row 4, in columns `_c2` to `_c20`. Rename these columns using the values in that row, replacing spaces with underscores and `&` with `and`. For example `90 & over` becomes `90_and_over`.
# MAGIC 2. Rename `_c0` to `population` and `_c1` to `year`.
# MAGIC 3. The bottom 7 rows are notes. Remove them.
# MAGIC 4. The file holds three data sets stacked on top of each other: Persons, Males and Females. You can derive this from the first column, or from the row numbers:
# MAGIC    - Persons is rows 6 to 26
# MAGIC    - Males is rows 28 to 48
# MAGIC    - Females is rows 50 to 70
# MAGIC
# MAGIC    Create three DataFrames, one for each, called `df_persons`, `df_males` and `df_females`. Each should have the `population` column filled on every row.
# MAGIC 5. Display `df_persons` in tabular form.
# MAGIC
# MAGIC The output for `df_persons` should look similar to the image below.

# COMMAND ----------

# MAGIC %md-sandbox
# MAGIC <img src="data:image/png;base64," alt="Task 3 expected output" style="max-width:100%; height:auto; border:1px solid #ddd;"/>

# COMMAND ----------

# DBTITLE 1,Task 3 Code
df=df_csv
w = Window.orderBy(F.monotonically_increasing_id())
df = df.withColumn("row_num", F.row_number().over(w))

header_row_num=4
header_row = (
    df.filter(F.col("row_num") == header_row_num)
        .select(*[f"_c{i}" for i in range(2, 21)])
      .first()
)
new_columns=[str(col).replace(' ', '_').replace('&','and') for col in header_row]

print(f"new_columns: {new_columns}")

for i, new_col in enumerate(new_columns, start=2):
    df = df.withColumnRenamed(f"_c{i}", new_col)

#renaming the first two columns
df = (
    df.withColumnRenamed("_c0", "population")
      .withColumnRenamed("_c1", "year")
)

# Remove last 7 rows 
total_rows = df.count()
print(f"Total rows: {total_rows}")
df = (
    df.filter(F.col("row_num") <= total_rows - 7)
)
print(f"Total rows after removing last 7 rows: {df.count()}")

# #Additional filtering (There are rows with all columns except rownumber/row_id as Null/None )
cols_to_check = [c for c in df.columns if c not in  ["row_num"]]
df = df.dropna(how="all", subset=cols_to_check)
###############

df = df.withColumn(
    "population",
    F.last("population", ignorenulls=True).over(
        Window.orderBy("row_num").rowsBetween(Window.unboundedPreceding, Window.currentRow)
    )
)

# COMMAND ----------

df_persons = df.filter(F.trim(F.col("population")) == "Persons").drop("row_num")
df_males   = df.filter(F.trim(F.col("population")) == "Males").drop("row_num")
df_females = df.filter(F.trim(F.col("population")) == "Females").drop("row_num")


#count of each df
print(f"df_persons: {df_persons.count()}")
print(f"df_males: {df_males.count()}")
print(f"df_females: {df_females.count()}")

display(df_persons)

# COMMAND ----------

# MAGIC %md
# MAGIC ### Task 4: Data analysis
# MAGIC
# MAGIC 1. The counts in the file are stored as text with thousands separators, for example `350,700`. Convert the `90_and_over` column in each of the three DataFrames to an integer.
# MAGIC 2. Join `df_females` and `df_males` to `df_persons` on `year`.
# MAGIC 3. For each year, calculate the percentage split of the `90_and_over` population between females and males, to two decimal places.
# MAGIC 4. Display the result with these columns: `year`, `90_and_over_num_persons`, `90_and_over_pcnt_females`, `90_and_over_num_females`, `90_and_over_pcnt_males`, `90_and_over_num_males`.
# MAGIC
# MAGIC The output should look similar to the image below.

# COMMAND ----------

# MAGIC %md-sandbox
# MAGIC <img src="data:image/png;base64," alt="Task 4 expected output" style="max-width:100%; height:auto; border:1px solid #ddd;"/>

# COMMAND ----------

# DBTITLE 1,Task 4 Code
for i in ['males','females','persons']:
    globals()[f"df_{i}_1"]=eval(f"df_{i}").select("year", F.col("90_and_over").alias(f"90_and_over_num_{i}"))

    globals()[f"df_{i}_1"]=eval(f"df_{i}_1").withColumn(f"90_and_over_num_{i}", F.regexp_replace(F.col(f"90_and_over_num_{i}"), ",", "").cast("int"))
        
    print(f"df_{i}_1: {eval(f'df_{i}_1').count()}")

# COMMAND ----------

df_result = df_persons_1.join(df_males_1, "year", "inner").join(df_females_1, "year", "inner")

for i in ["females", "males"]:
    df_result = df_result.withColumn(
        f"90_and_over_pcnt_{i}",
        F.concat(
            F.round(
                (F.col(f"90_and_over_num_{i}") /
                 F.col("90_and_over_num_persons")) * 100,
                2
            ).cast("string"),
            F.lit("%")
        )
    )
df_result=df_result.select("year", "90_and_over_num_persons", "90_and_over_num_females", "90_and_over_pcnt_females", "90_and_over_num_males", "90_and_over_pcnt_males")
df_result.display()

# COMMAND ----------

